// Command gentransitions writes deck/transitions_gen.go: the CSS keyframes of
// marp-cli's built-in transitions (fade, cover, cube, ...), taken from the
// bundle of an installed marp-cli, where they are one JavaScript object.
//
//	go run ./internal/cmd/gentransitions \
//	  $(brew --prefix marp-cli)/libexec/lib/node_modules/@marp-team/marp-cli/lib/marp-cli-*.js \
//	  > deck/transitions_gen.go
//
// marp-cli is MIT licensed (Copyright (c) Marp team); the keyframes are its
// work, and the generated file says so.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"sort"
	"strconv"
	"strings"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: gentransitions marp-cli-bundle.js")
		os.Exit(2)
	}
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	out, err := generate(string(src))
	if err != nil {
		fmt.Fprintln(os.Stderr, "gentransitions:", err)
		os.Exit(1)
	}
	os.Stdout.Write(out)
}

// entry is a built-in transition: its name, in the bundle's order, and its CSS
// ("" for none, which the bundle sets to false).
type entry struct{ name, css string }

// generate finds the object literal `Fi={clockwise:"...",...,none:!1}` that
// holds the keyframes, which the minifier named Fi, by the shape of its first
// entry, and writes the Go source.
func generate(src string) ([]byte, error) {
	const marker = `={clockwise:"@keyframes marp-incoming-transition-__builtin__clockwise`
	i := strings.Index(src, marker)
	if i < 0 {
		return nil, fmt.Errorf("the object of built-in transitions was not found (marp-cli changed?)")
	}
	entries, err := parseObject(src[i+1:])
	if err != nil {
		return nil, err
	}
	if len(entries) < 20 {
		return nil, fmt.Errorf("only %d transitions found; marp-cli 4.5.1 has more than 20", len(entries))
	}
	var b bytes.Buffer
	b.WriteString("// Code generated by internal/cmd/gentransitions from marp-cli's bundle; DO NOT EDIT.\n//\n")
	b.WriteString("// The keyframes are marp-cli's (https://github.com/marp-team/marp-cli),\n")
	b.WriteString("// MIT License, Copyright (c) 2017 Marp team.\n\n")
	b.WriteString("package deck\n\n")
	b.WriteString("// builtinTransitions holds the CSS of marp-cli's built-in transitions, by name,\n")
	b.WriteString("// in the order marp-cli lists them. The CSS of a name is written into a page that\n")
	b.WriteString("// uses it.\n")
	b.WriteString("var builtinTransitions = map[string]string{\n")
	var names []string
	for _, e := range entries {
		if e.css == "" {
			continue
		}
		fmt.Fprintf(&b, "\t%s: %s,\n", strconv.Quote(e.name), strconv.Quote(e.css))
		names = append(names, e.name)
	}
	b.WriteString("}\n\n")
	sort.Strings(names)
	b.WriteString("// BuiltinTransitionNames lists the built-in transitions, sorted.\n")
	b.WriteString("var BuiltinTransitionNames = []string{")
	for i, n := range names {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString(strconv.Quote(n))
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}

// parseObject reads a JavaScript object literal of identifier or string keys
// and double-quoted string values (or !1 for false), starting at the "{".
func parseObject(s string) ([]entry, error) {
	p := 0
	skip := func() {
		for p < len(s) && (s[p] == ' ' || s[p] == '\n' || s[p] == '\t') {
			p++
		}
	}
	expect := func(c byte) error {
		skip()
		if p >= len(s) || s[p] != c {
			return fmt.Errorf("at %d: want %q, have %q", p, c, around(s, p))
		}
		p++
		return nil
	}
	if err := expect('{'); err != nil {
		return nil, err
	}
	var out []entry
	for {
		skip()
		if p < len(s) && s[p] == '}' {
			return out, nil
		}
		// key
		var key string
		switch {
		case p < len(s) && s[p] == '"':
			k, n, err := readString(s[p:])
			if err != nil {
				return nil, err
			}
			key, p = k, p+n
		default:
			st := p
			for p < len(s) && (s[p] == '_' || s[p] == '$' || s[p] == '-' || s[p] >= '0' && s[p] <= '9' || s[p] >= 'a' && s[p] <= 'z' || s[p] >= 'A' && s[p] <= 'Z') {
				p++
			}
			if st == p {
				return nil, fmt.Errorf("at %d: no key: %q", p, around(s, p))
			}
			key = s[st:p]
		}
		if err := expect(':'); err != nil {
			return nil, err
		}
		skip()
		e := entry{name: key}
		switch {
		case strings.HasPrefix(s[p:], "!1"):
			p += 2
		case p < len(s) && (s[p] == '"' || s[p] == '\''):
			v, n, err := readString(s[p:])
			if err != nil {
				return nil, err
			}
			e.css, p = v, p+n
		default:
			return nil, fmt.Errorf("at %d: value of %s is not a string: %q", p, key, around(s, p))
		}
		out = append(out, e)
		skip()
		if p < len(s) && s[p] == ',' {
			p++
		}
	}
}

// readString reads a JavaScript string in double or single quotes (the
// minifier takes the one that needs fewer escapes), with the escapes minified
// CSS can contain, and returns it and the bytes it took.
func readString(s string) (string, int, error) {
	var b strings.Builder
	q := s[0]
	for i := 1; i < len(s); i++ {
		switch c := s[i]; c {
		case q:
			return b.String(), i + 1, nil
		case '\\':
			i++
			if i >= len(s) {
				return "", 0, fmt.Errorf("unterminated string")
			}
			switch e := s[i]; e {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case '\\', '"', '\'', '/':
				b.WriteByte(e)
			default:
				return "", 0, fmt.Errorf("unsupported escape \\%c in a CSS string", e)
			}
		default:
			b.WriteByte(c)
		}
	}
	return "", 0, fmt.Errorf("unterminated string")
}

func around(s string, p int) string {
	return s[p:min(len(s), p+40)]
}
